import React, { useState, useEffect, useCallback, useMemo, useRef } from "react";
import {
  Box,
  Typography,
  IconButton,
  Tooltip,
  alpha,
  useTheme,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  CircularProgress,
  Checkbox,
  Chip,
  InputAdornment,
  Avatar,
} from "@mui/material";
import {
  Visibility as ViewIcon,
  Notifications as NotificationIcon,
  Close as CloseIcon,
  Search as SearchIcon,
  KeyboardArrowDown as KeyboardArrowDownIcon,
} from "@mui/icons-material";
import DataTable from "../../../components/DataTable";
import DetailsModal from "../../../components/DetailsModal";
import { useSelector } from "react-redux";
import { useNavigate } from "react-router-dom";
import { toast } from "react-hot-toast";
import { mapNotificationExport } from "../../../utils/exportMappers";
import { extractExportList, performExport } from "../../../utils/exportHelpers";
import dayjs from "dayjs";

const BASE_URL = process.env.REACT_APP_API_BASE_URL;

const truncate = (str, n = 15) => {
  if (!str) return "-";
  return str.length > n ? str.substr(0, n) + "..." : str;
};

const BroadcastNotifications = () => {
  const theme = useTheme();
  const navigate = useNavigate();
  const [notifications, setNotifications] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [totalCount, setTotalCount] = useState(0);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(5);
  const [orderBy, setOrderBy] = useState("created_at");
  const [order, setOrder] = useState("desc");
  const [searchTerm, setSearchTerm] = useState("");
  const [isExporting, setIsExporting] = useState(false);

  const [openViewModal, setOpenViewModal] = useState(false);
  const [selectedNotification, setSelectedNotification] = useState(null);

  const token = useSelector((state) => state.auth.token);

  // ── Fetch Notifications ────────────────────────────────────────────────────
  const fetchNotifications = useCallback(
    async (apiPage, limit) => {
      if (!token) return;
      setIsLoading(true);
      try {
        const queryParams = new URLSearchParams({
          page: apiPage,
          limit: limit,
          sort_by: orderBy,
          sort_order: order,
          q: searchTerm,
        });

        const res = await fetch(
          `${BASE_URL}/notifications/admin/sent?${queryParams.toString()}`,
          {
            method: "GET",
            headers: {
              Authorization: `Bearer ${token}`,
              "Content-Type": "application/json",
            },
          },
        );
        const json = await res.json();
        if (!res.ok || json.error) {
          throw new Error(json.message || "Failed to fetch notifications");
        }
        setNotifications(json.data.sent_notifications || []);
        setTotalCount(json.data.pagination?.total || 0);
      } catch (err) {
        console.error("Error fetching notifications:", err);
        if (err.message !== "Failed to fetch") {
          toast.error(err.message || "Something went wrong while fetching");
        }
      } finally {
        setIsLoading(false);
      }
    },
    [token, orderBy, order, searchTerm],
  );

  useEffect(() => {
    if (token) {
      fetchNotifications(page + 1, rowsPerPage);
    }
  }, [page, rowsPerPage, fetchNotifications, token]);

  const handleSortChange = (property) => {
    const isAsc = orderBy === property && order === "asc";
    setOrder(isAsc ? "desc" : "asc");
    setOrderBy(property);
    setPage(0);
  };

  const handleViewDetails = (notification) => {
    setSelectedNotification(notification);
    setOpenViewModal(true);
  };

  const handleExportNotifications = useCallback(async (dates, format) => {
    if (!token) return;
    const toastId = toast.loading(`Exporting notifications as ${format.toUpperCase()}...`);
    setIsExporting(true);
    try {
      const queryParams = new URLSearchParams({
        q: searchTerm,
        sort_by: orderBy,
        sort_order: order,
        not_pagination: "true",
        start_date: dates.startDate.format('YYYY-MM-DD'),
        end_date: dates.endDate.format('YYYY-MM-DD'),
      });

      const res = await fetch(
        `${BASE_URL}/notifications/admin/sent?${queryParams.toString()}`,
        {
          method: "GET",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        },
      );

      const json = await res.json();
      if (!res.ok || json.error) {
        throw new Error(
          json.message || "Failed to fetch notifications for export",
        );
      }

      const items = extractExportList(json, 'sent_notifications');
      const filename = `Sent_Notifications_${dates.startDate.format('YYYYMMDD')}_to_${dates.endDate.format('YYYYMMDD')}`;

      await performExport({
        items,
        mapper: mapNotificationExport,
        format,
        filename,
        sheetName: 'Notifications',
        entityName: 'notifications',
        toastId,
      });
    } catch (err) {
      console.error("Export error:", err);
      toast.error(err.message || "Something went wrong while exporting", {
        id: toastId,
      });
    } finally {
      setIsExporting(false);
    }
  }, [token, searchTerm, orderBy, order]);

  const columns = [
    {
      id: "title",
      label: "Title",
      sortable: true,
      render: (row) => (
        <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
          <Box
            sx={{
              width: 36,
              height: 36,
              borderRadius: "10px",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              bgcolor: alpha(theme.palette.primary.main, 0.1),
              color: theme.palette.primary.main,
            }}
          >
            <NotificationIcon sx={{ fontSize: 20 }} />
          </Box>
          <Box>
            <Typography
              sx={{ color: "#FFFFFF", fontWeight: 600, fontSize: "0.875rem" }}
            >
              {truncate(row.title, 30)}
            </Typography>
            <Typography variant="caption" sx={{ color: "#8B8D97" }}>
              {row.recipients_count || 0} Recipients
            </Typography>
          </Box>
        </Box>
      ),
    },
    {
      id: "body",
      label: "Message",
      sortable: true,
      render: (row) => (
        <Typography sx={{ color: "#FFFFFF", fontSize: "0.875rem" }}>
          {truncate(row.body, 40)}
        </Typography>
      ),
    },
    {
      id: "created_at",
      label: "Date Sent",
      sortable: true,
      render: (row) => (
        <Typography sx={{ color: "#8B8D97", fontSize: "0.875rem" }}>
          {row.created_at
            ? new Date(row.created_at).toLocaleDateString("en-US", {
                month: "short",
                day: "numeric",
                year: "numeric",
                hour: "2-digit",
                minute: "2-digit",
              })
            : "-"}
        </Typography>
      ),
    },
    {
      id: "actions",
      label: "Actions",
      render: (row) => (
        <Box sx={{ display: "flex", gap: 1 }}>
          <Tooltip title="View Details">
            <IconButton
              size="small"
              onClick={() => handleViewDetails(row)}
              sx={{
                color: "#9F6EDA",
                bgcolor: alpha("#9F6EDA", 0.1),
                "&:hover": { bgcolor: alpha("#9F6EDA", 0.2) },
              }}
            >
              <ViewIcon fontSize="small" />
            </IconButton>
          </Tooltip>
        </Box>
      ),
    },
  ];

  const detailsData = useMemo(() => {
    if (!selectedNotification) return [];
    return [
      { label: "Notification Title", value: selectedNotification.title || "-" },
      {
        label: "Recipients",
        value: `${selectedNotification.recipients_count || 0} Users`,
      },
      {
        label: "Message Body",
        value: selectedNotification.body || "-",
        vertical: true,
      },
      {
        label: "Date Sent",
        value: selectedNotification.created_at
          ? new Date(selectedNotification.created_at).toLocaleString()
          : "N/A",
      },
    ];
  }, [selectedNotification]);

  return (
    <Box sx={{ p: { xs: 1, md: 3 } }}>
      <DataTable
        title="Notifications"
        columns={columns}
        data={notifications}
        isLoading={isLoading}
        searchTerm={searchTerm}
        onSearchChange={(val) => {
          setSearchTerm(val);
          setPage(0);
        }}
        orderBy={orderBy}
        order={order}
        onSortChange={handleSortChange}
        onExport={handleExportNotifications}
        isExporting={isExporting}
        onAddClick={() => navigate("/send-notification")}
        addLabel="Send Notification"
        pagination={{
          page: page,
          rowsPerPage: rowsPerPage,
          totalCount: totalCount,
          onPageChange: (_, newPage) => setPage(newPage),
          onRowsPerPageChange: (e) => {
            setRowsPerPage(parseInt(e.target.value, 10));
            setPage(0);
          },
        }}
        emptyTitle="No notifications found"
        emptyMessage="You haven't sent any notifications yet."
      />

      {/* View Notification Modal */}
      {selectedNotification && (
        <DetailsModal
          open={openViewModal}
          onClose={() => setOpenViewModal(false)}
          title="Notification Details"
          data={detailsData}
          maxWidth="sm"
        />
      )}
    </Box>
  );
};

export default BroadcastNotifications;
